// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Runtime.CompilerServices;
using System.Threading;
using Campground.Shared.Contracts;
using Campground.Shared.Injection;
using Microsoft.Extensions.Hosting;

namespace Campground.Shared.Registry
{
    /// <summary>
    /// Keeps the registry honest across Jellyfin 12's in-process restart (issue #33).
    /// <para>
    /// Jellyfin 12 restarts by building a new host in the same process and loading every plugin again into a new
    /// load context. The registry is an AppDomain slot, so it outlives that, still holding delegates into the old
    /// copies. Two things clean it up:
    /// </para>
    /// <list type="number">
    /// <item>On <c>ApplicationStopping</c>, each registered plugin withdraws its capabilities, its event
    /// subscriptions, its scripts, its activities, its session tags, its announcement, its browser runtime
    /// offer and its ownership registration (0.8.0), and the index.html election is cleared.</item>
    /// <item>A <b>host generation</b>: the <see cref="IHostApplicationLifetime"/> instance is new in each host, so the
    /// first copy to register with a new one opens a new generation. Every entry is stamped with the generation of
    /// the copy that wrote it, and anything stamped with an older one is dropped and never counted. That covers a
    /// plugin whose stop threw, or that was removed before the restart.</item>
    /// </list>
    /// <para>
    /// A 0.5.0 or 0.6.0 copy writes no stamps. Whatever is in the registry when the old host stops is stamped then,
    /// by the first copy that sees it stop, so their entries go with the old generation too. What they write after
    /// the new generation opens is unstamped and kept.
    /// </para>
    /// <para>
    /// The encoder ledger is left alone on purpose: GameTent's encoders outlive the restart and are taken over with
    /// <see cref="EncoderLedger.Adopt"/>, and leases expire by heartbeat instead (PR #35).
    /// </para>
    /// <para>
    /// The browser runtime offer is half in: a 0.7.0 copy's offer is stamped and goes with its generation, but an
    /// unstamped 0.5.0 or 0.6.0 offer is never stamped on stop. A 0.5.0 copy offers once, and in the new host its
    /// offer loses to the old one of the same version, so sweeping the old one would leave it with none. The cost:
    /// a removed 0.5.0 or 0.6.0 plugin's runtime is still offered until the process stops. Only the newest version
    /// is served, so that matters only while no 0.7.0 copy is installed.
    /// </para>
    /// <para>
    /// Every plugin calls <see cref="Register"/> once at start. <c>AddCampgroundInjection</c>'s startup filter does it
    /// for you; a plugin without scripts calls it from a hosted service or wherever it first has the lifetime.
    /// Background work is still the plugin's own job: stop it and wait for it on <c>ApplicationStopping</c>.
    /// </para>
    /// </summary>
    internal static class CampgroundLifetime
    {
        // Registry layout (section "lifetime"), all BCL types:
        //   "generation"    string, the current generation id
        //   "generationKey" WeakReference<object>, the IHostApplicationLifetime that opened it (weak, so the old host
        //                   isn't kept alive by the slot)
        //   "closed"        string, the last generation that was stamped on stop
        //   "stamps"        ConditionalWeakTable<object, object>: registry value -> generation id (string). Weak keys,
        //                   so a stamp goes away with the value it describes.
        // Every write to "generation", "generationKey" and "closed" happens under lock (section). The section
        // dictionary is the same object for every copy, so it is a lock they all agree on. "stamps" is thread-safe
        // on its own and needs no lock.
        private const string SectionName = "lifetime";

        // This copy's state. Statics are per load context, so each loaded copy has its own.
        // _copyGeneration: written under CopyGate, read with Volatile.Read.
        // Registered: read and written only under CopyGate.
        private static readonly object CopyGate = new();
        private static readonly Dictionary<string, IHostApplicationLifetime> Registered = new(StringComparer.Ordinal);
        private static string? _copyGeneration;

        /// <summary>The generation this copy belongs to, or null if it never registered (its writes go unstamped).</summary>
        internal static string? CopyGeneration => Volatile.Read(ref _copyGeneration);

        /// <summary>The current host generation, or null if no copy from 0.7.0 on has registered in this process.</summary>
        internal static string? CurrentGeneration
            => CampgroundRegistry.Section(SectionName).TryGetValue("generation", out var g) ? g as string : null;

        /// <summary>
        /// Joins this plugin to the host's lifetime: opens a new generation if this host is new, and withdraws the
        /// plugin's entries when the host stops. Safe to call more than once.
        /// </summary>
        internal static void Register(string pluginId, IHostApplicationLifetime lifetime)
        {
            var generation = OpenGeneration(lifetime);
            bool isNew;
            lock (CopyGate)
            {
                Volatile.Write(ref _copyGeneration, generation);
                isNew = !(Registered.TryGetValue(pluginId, out var known) && ReferenceEquals(known, lifetime));
                Registered[pluginId] = lifetime;
            }

            // After the generation opened (and swept): an offer made earlier in start-up is stamped now, or made
            // again if the old host's entry beat it to the slot.
            InjectionCoordinator.OfferRuntimeAgain();
            if (isNew)
            {
                lifetime.ApplicationStopping.Register(() => Stopping(pluginId, generation));
            }
        }

        /// <summary>Stamps a value this copy is about to store in the registry with this copy's generation.</summary>
        internal static void Stamp(object value)
        {
            var generation = CopyGeneration;
            if (generation != null)
            {
                Stamps().AddOrUpdate(value, generation);
            }
        }

        /// <summary>True when <paramref name="value"/> was written under an older generation. Readers skip it.</summary>
        internal static bool IsStale(object value)
        {
            var current = CurrentGeneration;
            return current != null
                && Stamps().TryGetValue(value, out var g)
                && !string.Equals(g as string, current, StringComparison.Ordinal);
        }

        /// <summary>True when <paramref name="generation"/> (a stamp stored as a plain string) is older than the current one.</summary>
        internal static bool IsStaleGeneration(string? generation)
        {
            var current = CurrentGeneration;
            return current != null && generation != null && !string.Equals(generation, current, StringComparison.Ordinal);
        }

        /// <summary>For tests only: forget the generation, the stamps and this copy's registrations.</summary>
        internal static void ResetForTests()
        {
            CampgroundRegistry.Section(SectionName).Clear();
            lock (CopyGate)
            {
                Registered.Clear();
                Volatile.Write(ref _copyGeneration, null);
            }
        }

        private static string OpenGeneration(IHostApplicationLifetime lifetime)
        {
            var section = CampgroundRegistry.Section(SectionName);
            lock (section)
            {
                if (section.TryGetValue("generationKey", out var k) && k is WeakReference<object> weak
                    && weak.TryGetTarget(out var known) && ReferenceEquals(known, lifetime)
                    && section.TryGetValue("generation", out var g) && g is string current)
                {
                    return current;
                }

                var generation = Guid.NewGuid().ToString("N");
                section["generationKey"] = new WeakReference<object>(lifetime);
                section["generation"] = generation;
                Sweep();
                return generation;
            }
        }

        private static void Stopping(string pluginId, string generation)
        {
            // Each step on its own, so one failure doesn't stop the rest. The host is going away either way.
            Try(() => Close(generation));
            Try(() => Capabilities.WithdrawAll(pluginId));
            Try(() => InjectionCoordinator.Unregister(pluginId));
            Try(() => Sessions.WithdrawActivities(pluginId));
            Try(() => Sessions.WithdrawTags(pluginId));
            Try(() => PluginRegistry.Withdraw(pluginId));
            Try(() => Ownership.Withdraw(pluginId));
            Try(CampgroundEvents.WithdrawThisCopy);
            Try(InjectionCoordinator.WithdrawRuntime);
        }

        // Stamps everything still unstamped with the closing generation, once per generation, so a 0.5.0 copy's
        // entries (and anything a crashed plugin left) go when the next generation opens. Then clears the
        // index.html election: it belonged to this host.
        private static void Close(string generation)
        {
            var section = CampgroundRegistry.Section(SectionName);
            lock (section)
            {
                if (section.TryGetValue("closed", out var c) && string.Equals(c as string, generation, StringComparison.Ordinal))
                {
                    return;
                }

                section["closed"] = generation;
                var stamps = Stamps();
                foreach (var dict in Tracked())
                {
                    foreach (var pair in dict)
                    {
                        stamps.TryAdd(pair.Value, generation);
                    }
                }
            }

            InjectionCoordinator.ResetElection();
        }

        // Called under lock (lifetime section) when a generation opens. Removes only the exact value that was
        // stamped stale (TryRemove with the key and value), so an entry rewritten in the meantime stays.
        // The runtime offer is swept but not in Tracked(): Close leaves an unstamped (0.5.0) offer unstamped, so it is
        // kept, and only a 0.7.0 copy's stamped offer goes.
        private static void Sweep()
        {
            foreach (var dict in Tracked().Append(CampgroundRegistry.Section(InjectionCoordinator.RuntimeSection)))
            {
                foreach (var pair in dict)
                {
                    if (IsStale(pair.Value))
                    {
                        dict.TryRemove(pair);
                    }
                }
            }

            InjectionCoordinator.DropStaleElection();
        }

        // The sections the generation cleans: capabilities, event subscribers, script tags, activities, plugin
        // announcements, session tags and ownership. Not encoder.* and not the runtime offer (see the class comment).
        private static IEnumerable<ConcurrentDictionary<string, object>> Tracked()
        {
            foreach (var name in new[] { Capabilities.SectionName, CampgroundEvents.SectionName })
            {
                foreach (var value in CampgroundRegistry.Section(name).Values)
                {
                    if (value is ConcurrentDictionary<string, object> inner)
                    {
                        yield return inner;
                    }
                }
            }

            yield return CampgroundRegistry.Section(InjectionCoordinator.TagsSection);
            yield return CampgroundRegistry.Section(Sessions.ActivitiesSection);
            yield return CampgroundRegistry.Section(Sessions.TagsSection);
            yield return CampgroundRegistry.Section(PluginRegistry.SectionName);
            yield return CampgroundRegistry.Section(Ownership.SectionName);
        }

        private static ConditionalWeakTable<object, object> Stamps()
        {
            var section = CampgroundRegistry.Section(SectionName);
            if (section.GetOrAdd("stamps", _ => new ConditionalWeakTable<object, object>()) is ConditionalWeakTable<object, object> table)
            {
                return table;
            }

            // Wrong shape under the name: replace it rather than fail every writer.
            var fresh = new ConditionalWeakTable<object, object>();
            section["stamps"] = fresh;
            return fresh;
        }

        private static void Try(Action step)
        {
            try
            {
                step();
            }
            catch (Exception)
            {
                // Fail open: the next generation clears whatever this left.
            }
        }
    }
}
